function [e3,SS]=f3(xyz,N,x0,y0) 
 %大气透射率 
 z0=84; 
 SS=zeros(length(xyz),1); 
 for i=1:N 
 dHR=sqrt((xyz(i,1)-x0)^2+(xyz(i,2)-
y0)^2+(xyz(i,3)-z0)^2); 
 SS(i)=0.99321-0.0001176*dHR+1.97*10^-8*dHR^2; 
 end 
 e3=mean(SS); 
end 

